local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local cs_coroutine = import('XLua.cs_coroutine')
---@type BambooUtils
local BambooUtils = import('Game.UI.FightReady.UIBamboo.BambooUtils')
local Animator = CS.UnityEngine.Animator
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local WaitForSeconds = CS.UnityEngine.WaitForSeconds
local KCookie = CS.Engine.Lib.KCookie

---@class UIBambooChallengeNode           
---@field Root                          	UnityEngine.CanvasGroup                 
---@field BtnChallenge                  	UnityEngine.RectTransform               
---@field ImgLock                       	UnityEngine.RectTransform               
---@field Unlock                        	UnityEngine.RectTransform               
---@field Txtdifficulty                 	UnityEngine.RectTransform               
---@field Txtchallenge                  	UnityEngine.RectTransform               
---@field TxtBegin                      	UnityEngine.RectTransform               
---@field BtnArrowR                     	UnityEngine.RectTransform               
---@field BtnArrowL                     	UnityEngine.RectTransform               
local UIBambooChallengeNode = Class("UIBambooChallengeNode")
function UIBambooChallengeNode:__init() 
    self._activityUuid = 0 
    self._data = nil
    self._curChallengeLevel = 0    --当前挑战等级
    self._cb = nil
    self._maxChallengeLevel = 0    --最大挑战等级
end

function UIBambooChallengeNode:__delete()
    self._activityUuid = nil
    self._data = nil
    self._cb = nil
    self._maxChallengeLevel = nil
end

function UIBambooChallengeNode:Awake()
end

function UIBambooChallengeNode:Start()
    SetButtonAction(self.BtnArrowL, Bind(self, self.OnBtnLeft))
    SetButtonAction(self.BtnArrowR, Bind(self, self.OnBtnRight))
    SetButtonAction(self.Root, Bind(self, self.OnBtnChallenge))
end

function UIBambooChallengeNode:Refresh(data, activityUuid)
    activityUuid = checkNumber(activityUuid)
    if not data or activityUuid <= 0 then
        return
    end
    self._activityUuid = activityUuid
    self._data = data

    self._curChallengeLevel = BambooUtils.GetCurChallengeLevel(self._data.id)
    local lastQuestId = checkNumber(KCookie.Get("LastChallengeQuestId"))
    --有上一次的挑战
    if lastQuestId > 0 then
        local vo = QuestConfMgr:GetInstance():GetQuestVoById(lastQuestId)
        if vo then
            --同一个类型
            if checkNumber(vo.type) == checkNumber(self._data.id) then
                self._curChallengeLevel = checkNumber(vo.regionLevel)
            end
        end
    else
        self._curChallengeLevel = BambooUtils.GetCurChallengeLevel(self._data.id)
    end

    local t = BambooUtils.GetChallengeQuests(self._data.id)
    if t then
        self._maxChallengeLevel = table.count(t)
    else
        self._maxChallengeLevel = 0
    end

    self:FillSelf()
end

function UIBambooChallengeNode:FillSelf()
    local isUnlock, str = BambooUtils.IsUnlockChallengeChapter(self._data.id)
    CfUtils.SetActive(self.Unlock, isUnlock)
    CfUtils.SetActive(self.ImgLock, not isUnlock)
    CfUtils.FillText(self.TxtLock, str)
    CfUtils.FillText(self.Txtchallenge, self._data.name)

    if isUnlock then
        self:FillChallengeLevelInfo()
        CfUtils.FillText(self.UnlockNode.transform:Find("TxtNumberHard1"), CfUtils.ChangeNum(self._curChallengeLevel))
    end
    self:RefreshBtnImage()

    local questId = BambooUtils.GetChallengeQuestId(self._data.id, self._curChallengeLevel)
    local t = RewardConfMgr:GetInstance():GetQuestRewardData(questId, Constants.QuestRewardType.RegularReward)
    if t then
        local data = checkTable(t[1])
        CfUtils.FillImage(self.ImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(data.id))
        CfUtils.FillText(self.TxtNumber1, data.num)
    end
end

--挑战等级信息
function UIBambooChallengeNode:FillChallengeLevelInfo()
    --CfUtils.FillText(self.Txtchallenge, localize("挑战 _num_", {_num_ = CfUtils.ChangeNum(self._curChallengeLevel)}))
    CfUtils.FillText(self.TxtNumberHard, CfUtils.ChangeNum(self._curChallengeLevel))

    local questId = BambooUtils.GetChallengeQuestId(self._data.id, self._curChallengeLevel)
    local t = RewardConfMgr:GetInstance():GetQuestRewardData(questId, Constants.QuestRewardType.RegularReward)
    if t then
        local data = checkTable(t[1])
        CfUtils.FillImage(self.ImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(data.id))
        CfUtils.FillText(self.TxtNumber1, data.num)
    end
end

--左
function UIBambooChallengeNode:OnBtnLeft()
    if self._curChallengeLevel <= 1 then
        return
    end
    self._curChallengeLevel = self._curChallengeLevel - 1 
    self:FillChallengeLevelInfo()
    self:RefreshBtnImage()

    CfUtils.PlayAnimator(self.UnlockNode, "Min")

    cs_coroutine.start(function()
        coroutine.yield(WaitForSeconds(0.25))
        CfUtils.FillText(self.UnlockNode.transform:Find("TxtNumberHard1"), CfUtils.ChangeNum(self._curChallengeLevel))
    end)
end

--右
function UIBambooChallengeNode:OnBtnRight()
    if self._curChallengeLevel >= self._maxChallengeLevel then
        return
    end
    local targetLevel = self._curChallengeLevel + 1 

    local questId = BambooUtils.GetChallengeQuestId(self._data.id, targetLevel)
    if checkNumber(questId) == 0 then
        GameUtils.Toast(localize("没有该关卡信息"))
        return
    end

    local isUnlock, str = BambooUtils.IsUnlockChallengeQuest(questId)
    if isUnlock then
        self._curChallengeLevel = targetLevel
        self:FillChallengeLevelInfo()
        self:RefreshBtnImage()

        CfUtils.PlayAnimator(self.UnlockNode, "Add")
        cs_coroutine.start(function()
            coroutine.yield(WaitForSeconds(0.25))
            CfUtils.FillText(self.UnlockNode.transform:Find("TxtNumberHard1"), CfUtils.ChangeNum(self._curChallengeLevel))
        end)
    else
        GameUtils.Toast(str)
    end
end

function UIBambooChallengeNode:RefreshBtnImage()
    local level = self._curChallengeLevel
    self:FillLeftImage(level > 1)

    local rightTrue = false
    if level >= self._maxChallengeLevel then
        self:FillRightImage(false)
    else
        level = self._curChallengeLevel + 1
        local questId = BambooUtils.GetChallengeQuestId(self._data.id, level)
        if checkNumber(questId) == 0 then
            self:FillRightImage(false)
        elseif BambooUtils.IsUnlockChallengeQuest(questId) then
            self:FillRightImage(true)
            rightTrue = true
        else
            self:FillRightImage(false)
        end
    end
end

function UIBambooChallengeNode:FillRightImage(isTrue)
    CfUtils.SetUISwitchImage(self.ImgRight, isTrue and 1 or 2)
    CfUtils.SetUISwitchImage(self.BtnArrowR.transform:Find("ImgRight1"), isTrue and 1 or 2)

    --[[
    if isTrue then
        CfUtils.FillImage(self.ImgRight, "uiatlas/Bamboo/BambooCheckpoint/activity_Challenge_btn_aorrw_light01.png")
    else
        CfUtils.FillImage(self.ImgRight, "uiatlas/Bamboo/BambooCheckpoint/activity_Challenge_btn_aorrw_dark01.png")
    end
    ]]
end

function UIBambooChallengeNode:FillLeftImage(isTrue)
    CfUtils.SetUISwitchImage(self.ImgLeft, isTrue and 1 or 2)
    CfUtils.SetUISwitchImage(self.BtnArrowL.transform:Find("ImgLeft1"), isTrue and 1 or 2)
    --[[
    if isTrue then
        CfUtils.FillImage(self.ImgLeft, "uiatlas/Bamboo/BambooCheckpoint/activity_Challenge_btn_aorrw_light01.png")
    else
        CfUtils.FillImage(self.ImgLeft, "uiatlas/Bamboo/BambooCheckpoint/activity_Challenge_btn_aorrw_dark01.png")
    end
    ]]
end

--挑战
function UIBambooChallengeNode:OnBtnChallenge()
    local isUnlock, str = BambooUtils.IsUnlockChallengeChapter(self._data.id)
    if not isUnlock then
        GameUtils.Toast(str)
        return
    end

    local questId = BambooUtils.GetChallengeQuestId(self._data.id, self._curChallengeLevel)
    if checkNumber(questId) <= 0 then
        return
    end
    local t = BambooUtils.GetUpBuffGroupIds(BambooUtils.GetActivityId(self._activityUuid))
    local buffVos = {} 
    local _t = BambooUtils.GetAllUpData(t)
    if _t then
        for _, v in pairs(_t) do
            for k, vo in pairs(v) do
                table.insert(buffVos, vo)
            end
        end
    end
    local isThree = checkNumber(CS.Engine.Lib.KCookie.Get("BambooChallengeIsThree"))
    print(QuestConfMgr:GetInstance():IsCompleteAllCondition(questId))
    if not QuestConfMgr:GetInstance():IsCompleteAllCondition(questId) then
        isThree = 0
    end

    local maxNeedLevel = checkNumber(BambooUtils.GetCurChallengeLevel(self._data.id))
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    KCookie.Set("LastChallengeQuestId", 0)
    if vo then
        --小于应该挑战的才记
        if checkNumber(vo.regionLevel) < maxNeedLevel then
            KCookie.Set("LastChallengeQuestId", checkNumber(questId))
        end
    end
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = {isThreeTripleMode = (isThree == 1), levelId = questId, activityUuid = self._activityUuid, upBuffData = _t, buffGroupIds = buffVos}}, {
        {id = Constants.UITypeIds.UIBambooChallengeDialog},
    })
end 

function UIBambooChallengeNode:OnDestroy()
    if self._openCo then
        cs_coroutine.stop(self._openCo)
        self._openCo = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIBambooChallengeNode
